inputs = ['gb', 'dw', 'jhbgh', 'uk', 'bfhbkd']
outputs = ['gb', 'dw', 'jibgi', 'uk', 'budgbkd']

print("Analyzing each pair:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"Pair {i}: '{inp}' → '{outp}'")

    # Let's manually identify character changes
    min_len = min(len(inp), len(outp))
    changes = []
    for j in range(min_len):
        if inp[j] != outp[j]:
            changes.append((j, inp[j], outp[j]))

    # Check if there are length differences
    if len(inp) != len(outp):
        if len(inp) > len(outp):
            changes.append((f"removed_at_end", len(outp), "removed"))
        else:
            changes.append((f"added_at_end", len(inp), "added"))

    print(f"  Changes: {changes}")
    print()

